"""Build the local review pages and a public-media-only Shorts/Reels download pack."""
import pathlib,json,html,hashlib,csv,zipfile
ROOT=pathlib.Path(__file__).resolve().parents[2];BASE=ROOT/'video-projects/ca-2026-portrait';OUT=ROOT/'.video-production/portrait';esc=html.escape
STYLE='''body{margin:0;background:#f5f1e7;color:#263d50;font:17px/1.6 system-ui}main{max-width:1120px;margin:32px auto;padding:0 24px}a{color:#357f78}h1{font:42px/1.15 Georgia}.layout{display:grid;grid-template-columns:minmax(260px,420px) 1fr;gap:40px;align-items:start}video{width:100%;max-height:82vh;background:#263d50;border-radius:14px}button{font:inherit;color:#357f78;background:white;border:1px solid #b3c2bc;border-radius:7px;padding:9px 13px;margin:4px;cursor:pointer}small{color:#64726f}.links{display:flex;gap:16px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:24px}.card{background:white;border-radius:14px;padding:20px}.card img{width:100%;height:300px;object-fit:contain}.card h2{font-size:21px}@media(max-width:720px){.layout{display:block}video{max-height:75vh}h1{font-size:32px}}'''
def page(title,body,script=''):return f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><style>{STYLE}</style><main>{body}</main>{script}</html>'
SCRIPT="""<script>fetch('review-chapters.json').then(r=>r.json()).then(rows=>{const nav=document.querySelector('#chapters'),v=document.querySelector('video');for(const row of rows){const b=document.createElement('button');b.textContent=row.label;b.onclick=()=>{v.currentTime=row.seconds;v.play()};nav.append(b)}});</script>"""
manifest=[];cards=[]
for path in sorted(BASE.glob('prop-*/project.json')):
 p=json.loads(path.read_text());name=path.parent.name;out=OUT/name;assert (out/'explainer.mp4').exists();v=json.loads((out/'validation.json').read_text());assert v['explainer.mp4']['frames']==p['frames'];version=hashlib.sha256(path.read_bytes()).hexdigest()[:10];seconds=p['frames']/30;title=p['title'];poster='scenes/'+p['scenes'][0]['id']+'.jpg'
 chapters=[dict(label=s['label'],seconds=s['start_frame']/30) for s in p['scenes']];(out/'review-chapters.json').write_text(json.dumps(chapters,indent=2))
 description=f"{title}\n\nA short overview of the proposal and voting tradeoffs.\nFull explanation, sources and official voter guide: {p['website']}\n\n#California #Proposition{p['number']} #Shorts\n";(out/'posting-description.txt').write_text(description)
 body=f'<p><a href="../">← All portrait shorts</a></p><h1>{esc(title)}</h1><div class="layout"><video controls playsinline preload="metadata" poster="{poster}"><source src="explainer.mp4?v={version}" type="video/mp4"></video><section><p><strong>{seconds:.1f} seconds · 1080 × 1920 · 30 fps</strong><br>Excerpts from the original cleaned human recording, at natural speed.</p><p>Portrait teaser for Instagram Reels and YouTube Shorts, with animated illustrations, diagrams and burned-in captions.</p><div id="chapters"></div><p class="links"><a href="explainer.mp4?v={version}" download="ca-2026-{name}-portrait.mp4">Download captioned MP4</a><a href="clean.mp4?v={version}" download="ca-2026-{name}-portrait-clean.mp4">Without captions</a><a href="captions.srt" download>Subtitles</a><a href="posting-description.txt" download>Posting description</a></p><p><a href="../../human/{name}/">Watch the full landscape explainer</a></p><p><a href="{p["website"]}">Read the website explainer and sources</a></p><small>Shortened from the existing full explainer. Source-check date: {p["checked"]}. Additional detail and polling remain in the full version.</small></section></div>'
 (out/'index.html').write_text(page(title,body,SCRIPT));cards.append(f'<article class="card"><a href="{name}/"><img src="{name}/{poster}" alt="Proposition {p["number"]} portrait video"></a><h2>{esc(title)}</h2><p>{seconds:.1f} seconds · 9:16</p><p><a href="{name}/">Watch and download →</a></p></article>')
 manifest.append(dict(proposition=p['number'],title=title,seconds=round(seconds,3),width=1080,height=1920,fps=30,file=f'{name}/explainer.mp4',clean_file=f'{name}/clean.mp4',captions=f'{name}/captions.srt',description=f'{name}/posting-description.txt',sha256=hashlib.sha256((out/'explainer.mp4').read_bytes()).hexdigest()))
body=f'<p>CALIFORNIA 2026</p><h1>Big decisions.<br>Under a minute.</h1><p>All {len(manifest)} propositions, using the original human voice recordings. Portrait teasers for Instagram Reels and YouTube Shorts.</p><p class="links"><a href="ca-2026-portrait-shorts.zip" download>Download all 14 captioned shorts + descriptions</a><a href="../">Full-length landscape collection</a></p><div class="grid">'+''.join(cards)+'</div>'
(OUT/'index.html').write_text(page('California propositions — portrait shorts',body));(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');(BASE/'export-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
with (OUT/'manifest.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(manifest[0]));w.writeheader();w.writerows(manifest)
with zipfile.ZipFile(OUT/'ca-2026-portrait-shorts.zip','w',compression=zipfile.ZIP_STORED) as z:
 for m in manifest:
  name=f'prop-{m["proposition"]:02}'
  for source,dest in [('explainer.mp4',f'ca-2026-{name}-portrait.mp4'),('captions.srt',f'ca-2026-{name}.srt'),('posting-description.txt',f'ca-2026-{name}-description.txt')]:z.write(OUT/name/source,dest)
 z.write(OUT/'manifest.csv','manifest.csv')
print('Collection and download pack ready:',len(manifest),'videos')
